package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Dfp_multiply_TriageGen0Test {

    private Dfp fieldDfp;

    @Before
    public void setUp() {
        // Dfp is an immutable class, we obtain an instance via newInstance to access the field
        fieldDfp = Dfp.newInstance(1.0);
    }

    @Test
    public void testMultiply_PositiveInteger() {
        Dfp base = fieldDfp.newInstance(5);
        Dfp result = base.multiply(3);
        // 5 * 3 = 15
        assertEquals("5 * 3 should be 15", fieldDfp.newInstance(15), result);
    }

    @Test
    public void testMultiply_Zero() {
        Dfp base = fieldDfp.newInstance(10);
        Dfp result = base.multiply(0);
        // 10 * 0 = 0
        assertTrue("Multiplying by zero should result in zero", result.isZero());
        assertEquals(fieldDfp.getZero(), result);
    }

    @Test
    public void testMultiply_NegativeInteger() {
        Dfp base = fieldDfp.newInstance(4);
        Dfp result = base.multiply(-2);
        // 4 * -2 = -8
        assertEquals("4 * -2 should be -8", fieldDfp.newInstance(-8), result);
    }

    @Test
    public void testMultiply_NegativeBase() {
        Dfp base = fieldDfp.newInstance(-7);
        Dfp result = base.multiply(2);
        // -7 * 2 = -14
        assertEquals("-7 * 2 should be -14", fieldDfp.newInstance(-14), result);
    }

    @Test
    public void testMultiply_TwoNegatives() {
        Dfp base = fieldDfp.newInstance(-3);
        Dfp result = base.multiply(-4);
        // -3 * -4 = 12
        assertEquals("-3 * -4 should be 12", fieldDfp.newInstance(12), result);
    }

    @Test
    public void testMultiply_One() {
        Dfp base = fieldDfp.newInstance(123);
        Dfp result = base.multiply(1);
        assertEquals("Multiplying by 1 should return the same value", base, result);
    }

    @Test
    public void testMultiply_LargeInteger() {
        Dfp base = fieldDfp.newInstance(1000000);
        Dfp result = base.multiply(1000000);
        assertEquals("10^6 * 10^6 should be 10^12", fieldDfp.newInstance(1000000000000L), result);
    }

    @Test
    public void testMultiply_IntegerMinValue() {
        Dfp base = fieldDfp.newInstance(2);
        // Integer.MIN_VALUE is -2147483648
        Dfp result = base.multiply(Integer.MIN_VALUE);
        assertEquals("2 * Integer.MIN_VALUE", fieldDfp.newInstance(-4294967296L), result);
    }

    @Test
    public void testMultiply_IntegerMaxValue() {
        Dfp base = fieldDfp.newInstance(2);
        // Integer.MAX_VALUE is 2147483647
        Dfp result = base.multiply(Integer.MAX_VALUE);
        assertEquals("2 * Integer.MAX_VALUE", fieldDfp.newInstance(4294967294L), result);
    }
}
